#!/usr/bin/env bash
# ============================================================================
# VideoMind, Part 14a2: Next.js security update for the main site
# ============================================================================
# FOR THE rebuild BRANCH. It refuses to run on main: apply it on rebuild,
# check the preview, then fast forward main.
#
# The main site ran Next.js 14.2.5. Every 14.x release up to 14.2.33 is
# affected by the December 2025 React Server Components advisories
# (CVE-2025-55184, a denial of service, and CVE-2025-55183, source code
# exposure); 14.2.35 is the patched 14.2 release. This moves next and
# eslint-config-next to 14.2.35. The dashboard already uses it. No code
# changes; React stays 18.3.1.
#
#   FRONTEND   package.json and package-lock.json. Run npm install after
#
#   ./vm_next_patch.sh            apply (needs Part 14a on the branch)
#   ./vm_next_patch.sh --force    apply even if the files differ from GitHub
#   ./vm_next_patch.sh --revert   restore them from the latest backup
#
# Run from the repo root (dir containing backend/ and frontend/).
# ============================================================================
set -euo pipefail

MARKER="vm_next_patch"
STAMP="$(date +%Y%m%d-%H%M%S)"
BAKDIR=".vm_next_patch_backups"

ADD=(

)
MOD=(
  "frontend/package.json"
  "frontend/package-lock.json"
)
PRE_MOD=(
  "5c05750c2b3f1dd0dc9371bd0f37703dbcea62c43f81f620eeb06237509e038c"
  "2eafd96d4fbdfb1ec7205575c48567391bbe446dc81694bb50cdf37624d1dd3e"
)
NEW_MOD=(
  "9ee8ee5dd5f3c89ff30801a7f63a8d44644a13499f07cf66348c3b9ba2e07d75"
  "e1b57cfaae50813fa69191aa1bc177831f2b217cd29b2770a9ce4d01e7408f87"
)
NEW_ADD=(

)

say() { printf '  %s\n' "$1"; }
die() { printf 'ERROR: %s\n' "$1" >&2; exit 1; }
sha() {
  if command -v sha256sum >/dev/null 2>&1; then sha256sum "$1" | cut -d' ' -f1
  else shasum -a 256 "$1" | cut -d' ' -f1; fi
}
bname() { printf '%s' "$1" | sed 's#/#__#g'; }

[ -d frontend ] && [ -d backend ] || die "Run from repo root (dir with backend/ and frontend/)."

BRANCH="$(git rev-parse --abbrev-ref HEAD 2>/dev/null || true)"
if [ "$BRANCH" = "main" ]; then
  die "You are on main. This part is for the rebuild branch. Run: git checkout rebuild"
fi

restore_from() {
  local f
  for f in "${MOD[@]}"; do
    if [ -f "$1/$(bname "$f")" ]; then mkdir -p "$(dirname "$f")"; cp "$1/$(bname "$f")" "$f"; fi
  done
  for f in ${ADD[@]+"${ADD[@]}"}; do
    if [ -f "$1/$(bname "$f")" ]; then cp "$1/$(bname "$f")" "$f"; else rm -f "$f"; fi
  done
}

if [ "${1:-}" = "--revert" ]; then
  [ -d "$BAKDIR" ] || die "No backup dir. Nothing to revert."
  LATEST="$(ls -1d "$BAKDIR"/*/ 2>/dev/null | sort | tail -1)"
  [ -n "$LATEST" ] || die "No backups found."
  restore_from "${LATEST%/}"
  say "Restored 2 changed files, from $LATEST"
  exit 0
fi

FORCE=0
[ "${1:-}" = "--force" ] && FORCE=1

if grep -q '"next": "14.2.35"' "frontend/package.json"; then
  say "Already applied (frontend/package.json has next 14.2.35). Use --revert to undo."
  exit 0
fi

grep -q "vm_admin" backend/src/index.ts 2>/dev/null || die "Part 14a is not on this branch. Run: git pull origin rebuild"

# ---- pre image check: every file must match what this part was built on ----
check_pre() {
  [ -f "$1" ] || die "$1 not found. Nothing changed."
  if [ "$(sha "$1")" != "$2" ]; then
    if [ "$FORCE" = "1" ]; then say "WARNING: $1 differs from GitHub rebuild (368c6b4). Proceeding (--force)."
    else die "$1 differs from the GitHub rebuild version this part was built on (368c6b4). Nothing changed. Run git pull origin rebuild, push or stash local edits, or run again with --force."; fi
  fi
}
i=0; for f in "${MOD[@]}"; do check_pre "$f" "${PRE_MOD[$i]}"; i=$((i+1)); done
for f in ${ADD[@]+"${ADD[@]}"}; do
  if [ -f "$f" ] && [ "$FORCE" != "1" ]; then die "$f already exists but is not this part's version. Nothing changed. Run again with --force to overwrite it."; fi
done

# ---- decode + verify every payload BEFORE touching anything ----
TMPD="$(mktemp -d)"
trap 'rm -rf "$TMPD"' EXIT
verify() {
  [ -s "$1" ] || die "$3: base64 decode produced an empty file. Nothing written."
  [ "$(sha "$1")" = "$2" ] || die "$3: payload checksum mismatch (script was corrupted in transit). Nothing written."
}

