B64_M1
verify "$TMPD/m1" "${NEW_MOD[1]}" "frontend/package-lock.json"

grep -q '"next": "14.2.35"' "$TMPD/m0"                 || die "package.json payload is wrong. Aborting."
grep -q '"eslint-config-next": "14.2.35"' "$TMPD/m0"   || die "package.json payload is wrong. Aborting."
grep -q '"@aptos-labs/wallet-adapter-react"' "$TMPD/m0" || die "package.json payload lost a package. Aborting."
grep -q '"node_modules/next": {' "$TMPD/m1"            || die "package-lock.json payload is wrong. Aborting."
say "2 payloads decoded and verified."

# ---- backups ----
mkdir -p "$BAKDIR/$STAMP"
for f in "${MOD[@]}"; do cp "$f" "$BAKDIR/$STAMP/$(bname "$f")"; done
for f in ${ADD[@]+"${ADD[@]}"}; do if [ -f "$f" ]; then cp "$f" "$BAKDIR/$STAMP/$(bname "$f")"; fi; done
say "Backups saved to $BAKDIR/$STAMP/"

rollback() {
  restore_from "$BAKDIR/$STAMP"
  die "$1 All files restored from $BAKDIR/$STAMP."
}

# ---- write ----
i=0; for f in ${ADD[@]+"${ADD[@]}"}; do mkdir -p "$(dirname "$f")"; cp "$TMPD/a$i" "$f" || rollback "Could not write $f."; i=$((i+1)); done
i=0; for f in "${MOD[@]}"; do cp "$TMPD/m$i" "$f" || rollback "Could not write $f."; i=$((i+1)); done

i=0; for f in ${ADD[@]+"${ADD[@]}"}; do [ "$(sha "$f")" = "${NEW_ADD[$i]}" ] || rollback "$f write verify failed."; i=$((i+1)); done
i=0; for f in "${MOD[@]}"; do [ "$(sha "$f")" = "${NEW_MOD[$i]}" ] || rollback "$f write verify failed."; i=$((i+1)); done

say "Applied the Next.js 14.2.35 update (Part 14a2)."
say "Install and verify before pushing:"
say "  (cd frontend && npm install && npx tsc --noEmit && npm run build)"
say "Then commit and push rebuild, and fast forward main:"
say "  git checkout main && git pull origin main && git merge --ff-only origin/rebuild && git push origin main && git checkout rebuild"
say "Undo: ./vm_next_patch.sh --revert (then npm install in frontend)"
